-- 蔬菜商品批量导入（自动生成）
-- 生成时间：2026-05-11
USE `freshtime`;

-- 1) 建立临时导入表
DROP TEMPORARY TABLE IF EXISTS `tmp_veg_import`;
CREATE TEMPORARY TABLE `tmp_veg_import` (
  `name` varchar(128) NOT NULL,
  `category_id` bigint(20) NOT NULL,
  `main_image` varchar(512) NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) NULL,
  `stock` int(11) NOT NULL,
  `unit` varchar(16) NOT NULL,
  `is_recommend` tinyint(4) NOT NULL,
  `home_sort` int(11) NOT NULL,
  `keywords` varchar(255) NULL,
  `origin` varchar(32) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2) 导入源数据

-- 3) 写入 goods（已存在同名+同分类则跳过）
SELECT 1, t.`category_id`, t.`name`, t.`main_image`, NULL, NULL, t.`price`, t.`original_price`, t.`stock`, t.`unit`, 0, t.`is_recommend`, 0, NULL, NULL, NULL, 0, t.`home_sort`, 1, 1, t.`keywords`, t.`origin`
FROM `tmp_veg_import` t
WHERE NOT EXISTS (SELECT 1 FROM `goods` g WHERE g.`name` = t.`name` AND g.`category_id` = t.`category_id`);

-- 4) 补 goods_tag 映射
SELECT g.id, 101 FROM `goods` g JOIN `tmp_veg_import` t ON t.`name`=g.`name` AND t.`category_id`=g.`category_id` WHERE NOT EXISTS (SELECT 1 FROM `goods_tag` x WHERE x.`goods_id`=g.id AND x.`tag_id`=101);
SELECT g.id, 102 FROM `goods` g JOIN `tmp_veg_import` t ON t.`name`=g.`name` AND t.`category_id`=g.`category_id` WHERE t.`category_id` IN (3,6,8,10) AND NOT EXISTS (SELECT 1 FROM `goods_tag` x WHERE x.`goods_id`=g.id AND x.`tag_id`=102);
SELECT g.id, 103 FROM `goods` g JOIN `tmp_veg_import` t ON t.`name`=g.`name` AND t.`category_id`=g.`category_id` WHERE t.`category_id` IN (4,5,7,8,9) AND NOT EXISTS (SELECT 1 FROM `goods_tag` x WHERE x.`goods_id`=g.id AND x.`tag_id`=103);

-- 5) 导入结果校验
SELECT COUNT(*) AS imported_vegetables FROM `goods` g JOIN `tmp_veg_import` t ON t.`name`=g.`name` AND t.`category_id`=g.`category_id`;
SELECT c.`name` AS category_name, COUNT(*) AS goods_count FROM `goods` g JOIN `category` c ON c.id=g.category_id WHERE c.id IN (3,4,5,6,7,8,9,10) GROUP BY c.`name` ORDER BY c.id;
